practice-total-discount-dollars.solutionCode:
SELECT ROUND(
    SUM(quantity * unit_price * COALESCE(discount_pct, 0) / 100),
    2
) AS total_discount_amount
FROM sales_reporting;

practice-sum-completed-gross-sales.solutionCode:
SELECT SUM(quantity * unit_price) AS completed_gross_sales
FROM sales_reporting
WHERE order_status = 'Completed';

